-- Anatomy nodes, parents first (each from its home region; role is the stored role where one is kept; sort_order is legacy, written once)
insert into specialization.nodes as t (id, region_id, parent_id, kind, role, name, short_name, aliases, layer, surface_visibility, status, catalog_muscle_key, database_muscle, border, location, what_it_does, shape_note, caveats, sort_order) values
  ($$forearm.anterior$$, $$forearm$$, null, $$compartment$$, $$group$$, $$Anterior (flexor-pronator) compartment$$, $$Palm side$$, array[$$flexor compartment$$, $$forearm flexors$$], $$mixed$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$both$$, $$Palm side of the forearm, in a surface, a middle and a deep layer from the elbow to the wrist.$$, $$Bends the wrist and the fingers and turns the palm down.$$, $$Together these muscles make up most of the palm-side fullness of the forearm. Which muscle shapes which part of that outline cannot be read from the surface. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$A group, not a muscle: work is counted for the individual muscles inside it.$$], 0),
  ($$forearm.posterior$$, $$forearm$$, null, $$compartment$$, $$group$$, $$Posterior (extensor-supinator) compartment$$, $$Back side$$, array[$$extensor compartment$$, $$forearm extensors$$], $$mixed$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$both$$, $$Back of the forearm and its thumb-side edge, in a surface layer and a deep layer from the elbow to the wrist.$$, $$Straightens the wrist, the fingers and the thumb and turns the palm up. The brachioradialis, also in this group, bends the elbow.$$, $$Makes up the back of the forearm and, through the brachioradialis and the thumb-side wrist extensors, the thumb-side outline near the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$A group, not a muscle: work is counted for the individual muscles inside it.$$], 1),
  ($$upper_arm.biceps$$, $$upper_arm$$, null, $$muscle$$, $$external$$, $$Biceps brachii$$, $$Biceps$$, array[$$biceps$$], $$surface$$, $$clear$$, $$reviewed$$, $$biceps$$, $$biceps_brachii$$, null, $$Front of the upper arm, crossing the elbow to the radius.$$, $$Bends your elbow and turns your palm up; with the elbow bent it is the strongest palm-up muscle.$$, $$Shapes the front of the upper arm. It is an upper-arm muscle and does not add forearm size.$$, array[$$Shown only as another muscle that curls and palm-up turning load; not a forearm target.$$], 22),
  ($$upper_arm.brachialis$$, $$upper_arm$$, null, $$muscle$$, $$external$$, $$Brachialis$$, $$Brachialis$$, array[$$brachialis$$], $$deep$$, $$partial$$, $$reviewed$$, $$brachialis$$, $$brachialis$$, null, $$Front of the lower upper arm, under the biceps, crossing the elbow to the ulna.$$, $$Bends your elbow, whichever way the palm faces. It does not turn the forearm.$$, $$Mostly covered by the biceps; may show at the sides of the lower upper arm. It is not a forearm muscle.$$, array[$$Shown only as another muscle that curls load; not a forearm target.$$], 23),
  ($$forearm.br$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Brachioradialis$$, $$BR$$, array[$$brachioradialis$$], $$surface$$, $$clear$$, $$reviewed$$, $$forearms$$, $$brachioradialis$$, $$radial$$, $$Thumb side of the forearm, from just above the elbow to the wrist; the outermost muscle on that edge.$$, $$Bends your elbow. It works whichever way the palm faces; anatomy texts describe it as strongest with the thumb pointing up.$$, $$Contributes to the thumb-side contour of the upper forearm, the bulge just below the elbow. It does not bend the wrist. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Studies disagree on whether turning the palm up, sideways or down changes how hard it works in a curl.$$, $$From a fully palm-up or palm-down start it also turns the forearm back toward thumb-up; that is not counted as a separate action here.$$], 2),
  ($$forearm.fcr$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor carpi radialis$$, $$FCR$$, array[$$FCR$$, $$radial wrist flexor$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$radial$$, $$Palm side, surface layer, running at a slant from the pinky side of the elbow to the thumb side of the wrist.$$, $$Bends your wrist toward the palm and toward the thumb side.$$, $$May contribute to the palm-side contour toward the thumb side, between the elbow crease and mid-forearm. It is not the whole thumb-side width: the brachioradialis forms that edge. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Its tendon is easy to see at the wrist; a visible tendon is not muscle size.$$], 3),
  ($$forearm.fcu$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor carpi ulnaris$$, $$FCU$$, array[$$FCU$$, $$ulnar wrist flexor$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$ulnar$$, $$Palm side, surface layer, along the pinky-side edge from the elbow to the wrist.$$, $$Bends your wrist toward the palm and toward the pinky side.$$, $$Contributes to the palm-side contour along the pinky side (ulnar). Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[]::text[], 4),
  ($$forearm.pl$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Palmaris longus$$, $$PL$$, array[$$PL$$], $$surface$$, $$variable$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$central$$, $$Palm side, surface layer, down the middle: a short belly near the elbow and a long tendon to the palm.$$, $$Tenses the sheet of connective tissue in the palm and gives a little help bending the wrist.$$, $$Small belly and long tendon, and missing in some people, so it is not a major driver of forearm width. Visible shape depends far more on the muscles around it.$$, array[$$Absent on one or both sides in some people; how often varies widely between populations.$$, $$Its absence has not been shown to reduce grip strength.$$], 5),
  ($$forearm.fds$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor digitorum superficialis$$, $$FDS$$, array[$$FDS$$, $$superficial finger flexor$$, $$flexor digitorum sublimis$$], $$intermediate$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$central$$, $$Palm side, middle layer: under the surface wrist flexors and over the deep finger flexor.$$, $$Bends your four fingers at their middle joints, and helps bend the knuckles and the wrist. Each finger has its own part of the muscle, but the parts do not work fully apart.$$, $$May add to the general fullness of the palm side of the forearm. It lies under other muscles, so it has no separately visible outline.$$, array[$$Grip and finger-curl work loads it together with the deep finger flexor (FDP); how the work splits between them is not known.$$], 6),
  ($$forearm.fdp$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor digitorum profundus$$, $$FDP$$, array[$$FDP$$, $$deep finger flexor$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$ulnar$$, $$Palm side, deep layer, against the ulna on the pinky side and under the other finger flexors.$$, $$Bends your fingertips: it is the only muscle that bends the end joints of the four fingers. It also helps bend the middle joints, the knuckles and the wrist.$$, $$Deep bulk under the palm-side muscles. It may add to overall palm-side thickness but has little or no separately visible surface contour, so it is not drawn as a surface stripe.$$, array[$$Grip and finger-curl work loads it together with FDS; how the work splits between them is not known.$$], 7),
  ($$forearm.fpl$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor pollicis longus$$, $$FPL$$, array[$$FPL$$, $$long thumb flexor$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$radial$$, $$Palm side, deep layer, on the thumb side against the radius.$$, $$Bends the tip of your thumb, and helps bend the thumb at its knuckle. No other muscle bends the thumb tip.$$, $$Deep tissue on the thumb side of the palm side, close to the bone; little or no separately visible contour.$$, array[$$Hard to feel through the skin because it lies under the other flexors.$$], 8),
  ($$forearm.pt$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Pronator teres$$, $$PT$$, array[$$PT$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, null, $$central$$, $$Palm side just below the elbow, surface layer, slanting from the pinky side of the elbow to the middle of the radius on the thumb side.$$, $$Turns your palm down, and gives a little help bending the elbow.$$, $$May contribute to the slanted palm-side contour just below the elbow crease, where it forms the pinky-side edge of the hollow in front of the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Both pronators turn the palm down, so palm-down work loads it together with the pronator quadratus.$$], 9),
  ($$forearm.pq$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Pronator quadratus$$, $$PQ$$, array[$$PQ$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, null, $$both$$, $$Palm side, deepest layer: a flat, square muscle on the two forearm bones just above the wrist.$$, $$Turns your palm down, and helps hold the two forearm bones together near the wrist.$$, $$Deep and close to the bones near the wrist, under the flexor tendons; little or no direct surface definition.$$, array[$$Both pronators turn the palm down, so palm-down work loads it together with the pronator teres.$$], 10),
  ($$forearm.ecrl$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor carpi radialis longus$$, $$ECRL$$, array[$$ECRL$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm on the thumb side, starting just above the elbow beside the brachioradialis.$$, $$Bends your wrist back and toward the thumb side.$$, $$May contribute to the contour on the back and thumb side of the forearm near the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Ordinary exercises cannot train it apart from ECRB; the two are counted together in practice.$$], 11),
  ($$forearm.ecrb$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor carpi radialis brevis$$, $$ECRB$$, array[$$ECRB$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm on the thumb side, beside and partly under ECRL.$$, $$Bends your wrist back and toward the thumb side.$$, $$Part of the extensor mass on the back and thumb side of the forearm. Partly covered by ECRL, so its own outline is only partly visible. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Ordinary exercises cannot train it apart from ECRL; the two are counted together in practice.$$, $$In one study it was more active in wrist-extension holds with the palm turned down. That is short-term muscle activity, not growth.$$], 12),
  ($$forearm.ecu$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor carpi ulnaris$$, $$ECU$$, array[$$ECU$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$ulnar$$, $$Back of the forearm, surface layer, along the pinky-side edge from the elbow to the wrist.$$, $$Bends your wrist back and toward the pinky side.$$, $$May contribute to the contour along the back of the forearm on the pinky side. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[]::text[], 13),
  ($$forearm.ed$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor digitorum$$, $$ED$$, array[$$ED$$, $$extensor digitorum communis$$, $$EDC$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$central$$, $$Back of the forearm, surface layer, down the middle; it splits into four tendons that run to the fingers.$$, $$Straightens your four fingers, mainly at the knuckles, and helps bend the wrist back.$$, $$May contribute to the central mass on the back of the forearm. Its tendons on the back of the hand are tendon, not muscle bulk. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[]::text[], 14),
  ($$forearm.edm$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor digiti minimi$$, $$EDM$$, array[$$EDM$$, $$extensor digiti quinti$$], $$surface$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$ulnar$$, $$Back of the forearm, surface layer: a thin muscle on the pinky side of the extensor digitorum.$$, $$Straightens your little finger, on its own or with the other fingers.$$, $$Small, and joined to the extensor digitorum near the elbow; not a major independent driver of forearm width.$$, array[$$Some anatomists treat it as the pinky-side part of the extensor digitorum.$$], 15),
  ($$forearm.ei$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor indicis$$, $$EI$$, array[$$EI$$, $$extensor indicis proprius$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$central$$, $$Back of the forearm, deep layer near the wrist, arising on the pinky side; its tendon runs to the index finger.$$, $$Straightens your index finger, which lets it point on its own.$$, $$Small and deep near the wrist; little or no separately visible contour.$$, array[]::text[], 16),
  ($$forearm.apl$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Abductor pollicis longus$$, $$APL$$, array[$$APL$$], $$deep$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm, deep layer, coming to the surface on the thumb side above the wrist on its way to the base of the thumb.$$, $$Moves your thumb out from the hand at its base, away from the index finger, and helps straighten it there.$$, $$Mostly deep, with little separately visible contour. Near the wrist its tendon, with EPB's, forms the thumb-side edge of the hollow at the base of the thumb; a visible tendon there is not muscle size.$$, array[$$References disagree about a small effect at the wrist, so no wrist action is counted for it here.$$], 17),
  ($$forearm.epb$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor pollicis brevis$$, $$EPB$$, array[$$EPB$$], $$deep$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm, deep layer near the wrist on the thumb side, beside APL.$$, $$Straightens your thumb at its knuckle, and helps straighten it at its base.$$, $$Small and deep, with little separately visible contour. Its tendon at the base of the thumb can be easy to see; that is tendon, not muscle size.$$, array[$$Where its tendon attaches varies a good deal between people.$$], 18),
  ($$forearm.epl$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor pollicis longus$$, $$EPL$$, array[$$EPL$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$central$$, $$Back of the forearm, deep layer in the middle; a long tendon bends around a bony bump on the back of the radius to reach the thumb tip.$$, $$Straightens the tip of your thumb, and helps straighten the thumb at its knuckle.$$, $$Deep muscle with little or no separately visible contour. Its long tendon forms the pinky-side edge of the hollow at the base of the thumb; a visible tendon is not muscle size.$$, array[]::text[], 19),
  ($$forearm.supinator$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Supinator$$, $$SUP$$, array[$$supinator$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, null, $$radial$$, $$Just below the elbow on the back and thumb side, deep layer, wrapped around the top of the radius.$$, $$Turns your palm up.$$, $$Deep near the elbow, under the surface extensors; not directly visible in an ordinary surface view.$$, array[$$With the elbow bent the biceps is the stronger palm-up muscle, so palm-up work with a bent elbow is not supinator-only.$$], 20),
  ($$forearm.anconeus$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$adjacent$$, $$Anconeus$$, $$ANC$$, array[$$anconeus$$], $$surface$$, $$partial$$, $$reviewed$$, $$triceps$$, null, $$ulnar$$, $$Back of the elbow: a small triangle from the thumb-side bony knob of the upper-arm bone to the point of the elbow.$$, $$Helps straighten your elbow and steadies the joint; the triceps does most of the straightening.$$, $$Small; may add to the contour at the back of the elbow. It is not a forearm growth target.$$, array[$$Shown beside the forearm muscles because of where it sits; forearm specialization does not target it.$$], 21)
