-- Sources
insert into specialization.sources as t (source_key, url, title, doi, evidence_type, retrieved_on, notes) values
  ($$A1$$, $$https://www.ncbi.nlm.nih.gov/books/NBK526110/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Brachioradialis Muscle (Lung, Ekblad, Bisogno)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: active in elbow flexion with the forearm supinated, neutral or pronated; pronates from supination and supinates from pronation; one of two extensor-compartment muscles that do not cross the wrist; sits in the mobile wad with ECRL and ECRB; radial nerve. Updated 30 Jan 2024.$$),
  ($$A10$$, $$https://doi.org/10.1002/ca.22289$$, $$Yammine, Clinical prevalence of palmaris longus agenesis: a systematic review and meta-analysis (Clinical Anatomy 26(6):709–718, 2013)$$, $$10.1002/ca.22289$$, $$systematic_review$$, $$2026-10-16$$, $$Checked via web-search results (abstract): 26 clinical prevalence studies; the pooled absence rate was higher than the commonly quoted figure and varied strongly by population, lowest in East and South-East African subgroups and highest in Arab Middle Eastern groups; no significant sex difference. Clinical examination studies only.$$),
  ($$A11$$, $$https://radiopaedia.org/articles/23240$$, $$Radiopaedia: palmaris longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: absence frequency differs between populations (lower in Asian and African-American groups than in white and Hispanic groups).$$),
  ($$A12$$, $$https://www.ncbi.nlm.nih.gov/books/NBK539723/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Flexor Digitorum Superficialis Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the largest extrinsic forearm flexor; forms the intermediate layer between the superficial and deep groups; four digital components, each with its own tendon; the primary flexor of the PIP joints, also assisting MCP flexion; runs superficial to FDP and FPL.$$),
  ($$A13$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/flexor-digitorum-superficialis/20893$$, $$Elsevier Complete Anatomy, Quick Facts: flexor digitorum superficialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: flexes the middle phalanges, assists flexion at the MCP joints and assists flexion of the hand at the wrist.$$),
  ($$A14$$, $$https://pubmed.ncbi.nlm.nih.gov/30252302/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Flexor Digitorum Profundus Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: flexes the MCP and DIP joints of the medial four digits and is the only muscle that flexes the DIP joints; DIP flexion depends on wrist position and its tension falls when the wrist is fully flexed; tendons insert deep to the FDS tendons.$$),
  ($$A15$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/flexor-digitorum-profundus/18692$$, $$Elsevier Complete Anatomy, Quick Facts: flexor digitorum profundus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: DIP flexion is the primary action, with secondary roles at the PIP and MCP joints and the wrist; the index-finger part can flex on its own.$$),
  ($$A16$$, $$https://pubmed.ncbi.nlm.nih.gov/31408520/$$, $$Fox, Oliver, Nguyen, Hentz and Curtin, video electromyography of extrinsic and intrinsic finger flexors during grasp (Orthopedics 42(6):e555–e558, 2019)$$, null, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (abstract on a Stanford Health Care page, and a 2014 poster by the same group): light fist formation mainly used FDP with either FDS or the intrinsics; FDS and the intrinsics were recruited in every tight fist, in an order that differed between patients; FDP described as the workhorse of composite fist formation. Prospective cohort including injured hands. The exact article title was not confirmed.$$),
  ($$A17$$, $$https://www.statpearls.com/articlelibrary/viewarticle/36137/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Flexor Pollicis Longus Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction and start of the structure section): one of three deep flexors of the volar compartment; the main thumb flexor, acting at the MCP and IP joints; courses along the radial aspect of the volar forearm, deep and radial to the radial head of FDS; anterior interosseous nerve.$$),
  ($$A18$$, $$https://radiopaedia.org/articles/flexor-pollicis-longus$$, $$Radiopaedia: flexor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: action is flexion of the interphalangeal joint of the thumb; anterior interosseous nerve.$$),
  ($$A19$$, $$https://www.kenhub.com/en/library/anatomy/flexor-pollicis-longus-muscle$$, $$Kenhub: flexor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the only muscle that flexes the interphalangeal joint of the thumb; absent in a small part of the population and can blend with neighbouring flexors.$$),
  ($$A2$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/brachioradialis-muscle/23633$$, $$Elsevier Complete Anatomy, Quick Facts: brachioradialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: primarily flexes the elbow and is strongest in mid-pronation (citing Gray's Anatomy); its medial margin is the lateral boundary of the cubital fossa.$$),
  ($$A20$$, $$https://www.kenhub.com/en/library/anatomy/the-deep-flexors-of-the-forearm$$, $$Kenhub: deep anterior forearm muscles$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: FDP, FPL and pronator quadratus form the deep group; they run under FDS, very close to the radius and ulna, and are difficult to palpate.$$),
  ($$A21$$, $$https://www.statpearls.com/point-of-care/145103$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Pronator Teres$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: main action is pronation, with a small role in elbow flexion; humeral and ulnar heads with the median nerve between them; inserts on the lateral midshaft of the radius below the supinator; its lateral edge forms the medial border of the cubital fossa. The search reported this article's Bookshelf id as NBK580564; not opened directly.$$),
  ($$A22$$, $$https://www.kenhub.com/en/library/anatomy/pronator-teres-muscle$$, $$Kenhub: pronator teres muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: humeral head from the medial supracondylar ridge, ulnar head from the coronoid process; inserts on the lateral surface of the radius distal to the supinator; actions are forearm pronation and elbow flexion; median nerve.$$),
  ($$A23$$, $$https://radiopaedia.org/articles/pronator-quadratus$$, $$Radiopaedia: pronator quadratus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the most distal muscle of the deepest layer of the anterior compartment; from the distal quarter of the ulna to the distal quarter of the radius; pronates the forearm; anterior interosseous nerve.$$),
  ($$A24$$, $$https://www.kenhub.com/en/library/anatomy/pronator-quadratus-muscle$$, $$Kenhub: pronator quadratus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: flat, short, quadrilateral muscle; the deepest muscle of the anterior compartment; forearm pronation; anterior interosseous branch of the median nerve.$$),
  ($$A25$$, $$https://heibib.ub.uni-heidelberg.de/search/Record/1693802481$$, $$Spies et al., Anatomie und Biomechanik des distalen Radioulnargelenks (Anatomy and biomechanics of the distal radioulnar joint), Der Orthopäde 47(8):621–627, 2018$$, null, $$biomechanics$$, $$2026-10-16$$, $$Checked via web-search results (library record abstract): the triangular fibrocartilage complex is the main stabiliser; pronator quadratus is the relevant dynamic stabiliser of the DRUJ, and its contraction prevents diastasis of the joint. German-language review.$$),
  ($$A26$$, $$https://litfl.com/wp-content/uploads/2019/06/382.pdf$$, $$Tsai and Paksima, review of the distal radioulnar joint (2009; PDF hosted by LITFL)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: ECU and pronator quadratus are dynamic stabilisers of the DRUJ; the deep head of pronator quadratus is the prime stabiliser while the superficial head is the more powerful pronator. Journal details were not confirmed by the search.$$),
  ($$A27$$, $$https://www.kenhub.com/en/library/anatomy/extensor-carpi-radialis-longus-muscle$$, $$Kenhub: extensor carpi radialis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: inserts on the base of the second metacarpal; extends and abducts (radially deviates) the hand at the wrist; radial nerve.$$),
  ($$A28$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/extensor-carpi-radialis-longus/22064$$, $$Elsevier Complete Anatomy, Quick Facts: extensor carpi radialis longus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extends the hand at the wrist and abducts it at the radiocarpal and midcarpal joints.$$),
  ($$A29$$, $$https://www.ncbi.nlm.nih.gov/books/NBK539719/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Extensor Carpi Radialis Brevis Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: posterior superficial compartment; the prime dorsiflexor of the wrist; works with ECRL to extend and abduct the wrist; shorter than ECRL and partly covered by it; inserts on the base of the third metacarpal. Updated 28 Aug 2023.$$),
  ($$A3$$, $$https://www.kenhub.com/en/library/anatomy/brachioradialis-muscle$$, $$Kenhub: brachioradialis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the most superficial muscle on the radial aspect of the forearm, palpable as the fleshy prominence in the upper half of the lateral forearm with the elbow flexed and the forearm semi-pronated.$$),
  ($$A30$$, $$https://pubmed.ncbi.nlm.nih.gov/10969198/$$, $$A new technique for the selective recording of extensor carpi radialis longus and brevis (Journal of Electromyography and Kinesiology 10(4):249–253, 2000)$$, null, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (abstract): standard EMG texts held that ECRL and ECRB activity cannot be distinguished even with intramuscular electrodes; the authors placed fine-wire electrodes from cadaver measurements (10 specimens) and reported differentiated recordings in three volunteers. A methods paper, not a training study.$$),
  ($$A31$$, $$https://www.statpearls.com/point-of-care/36165$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Extensor Carpi Ulnaris Muscle (Sawyer, Sajjad, Tadi)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: posterior forearm muscle that primarily extends and adducts the wrist, with ECRL and ECRB for extension and with FCU for adduction; humeral and ulnar heads; inserts on the dorsal base of the fifth metacarpal via the sixth extensor compartment; posterior interosseous nerve.$$),
  ($$A32$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/extensor-digitorum/22591$$, $$Elsevier Complete Anatomy, Quick Facts: extensor digitorum$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extends the proximal phalanges at the MCP joints and the fingers at the interphalangeal joints; assists extension of the hand at the wrist.$$),
  ($$A33$$, $$https://www.kenhub.com/en/library/anatomy/extensor-digitorum-muscle$$, $$Kenhub: extensor digitorum muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: also participates in wrist extension; its belly ends in four tendons about a third of the way down the forearm, passing under the extensor retinaculum to digits 2–5.$$),
  ($$A34$$, $$https://www.ncbi.nlm.nih.gov/books/NBK534805/$$, $$StatPearls: wrist and finger extensor muscles (NBK534805)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extensor digitorum communis extends the index, middle, ring and little fingers; extensor indicis proprius independently extends the index finger; extensor digiti minimi independently extends the little finger. The article's exact title was not shown in the results (another site cites it as Wrist Extensor Muscles).$$),
  ($$A35$$, $$https://www.kenhub.com/en/library/anatomy/extensor-digiti-minimi-muscle$$, $$Kenhub: extensor digiti minimi muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: long, thin muscle of the superficial extensor group; proximal fibres usually fused with extensor digitorum, separate from about mid-forearm, just medial to it; extends the fifth digit at the MCP joint; posterior interosseous nerve.$$),
  ($$A36$$, $$https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/$$, $$University of Arkansas for Medical Sciences: muscles of the upper limb$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extensor digiti minimi inserts into the extensor expansion of the fifth digit, and some anatomists regard it as the ulnar-most part of extensor digitorum; extensor indicis arises from the distal posterior ulna and interosseous membrane, joins the index tendon of extensor digitorum and extends the index finger.$$),
  ($$A37$$, $$https://www.kenhub.com/en/library/anatomy/extensor-indicis-muscle$$, $$Kenhub: extensor indicis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: narrow, elongated deep extensor of the posterior compartment; extends the index finger at the MCP and interphalangeal joints, letting it extend on its own; weaker wrist-extension effect; posterior interosseous nerve.$$),
  ($$A38$$, $$https://anatomy.ttuhscep.edu/anatomytables/muscles_upperlimb.html$$, $$Texas Tech University Health Sciences Center El Paso: muscles of the upper limb, listed alphabetically$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (only some rows were shown): abductor pollicis longus abducts the thumb at the carpometacarpal joint; the tendons of abductor pollicis longus and extensor pollicis brevis form the lateral border of the anatomical snuffbox; anconeus runs from the lateral epicondyle to the olecranon and upper ulna and extends the forearm.$$),
  ($$A39$$, $$https://www.kenhub.com/en/library/anatomy/abductor-pollicis-longus-muscle$$, $$Kenhub: abductor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: abducts and extends the thumb at the carpometacarpal joint; the English article also lists extension of the hand at the wrist, while the German article and video describe radial deviation.$$),
  ($$A4$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC4526813/$$, $$Kleiber, Kunz and Disselhorst-Klug, Muscular coordination of biceps brachii and brachioradialis in elbow flexion with respect to hand position (Frontiers in Physiology, 2015)$$, $$10.3389/fphys.2015.00215$$, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (abstract): surface EMG, 16 healthy subjects, single elbow flexions at 20°/s with the hand pronated, neutral and supinated. Brachioradialis contribution differed significantly with the hand pronated compared with supinated and neutral; biceps activity did not change. Acute activity, not growth.$$),
  ($$A40$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/abductor-pollicis-longus/21696$$, $$Elsevier Complete Anatomy, Quick Facts: abductor pollicis longus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: abducts and extends the thumb at the first carpometacarpal joint; no wrist action listed.$$),
  ($$A41$$, $$https://www.kenhub.com/en/library/anatomy/extensor-pollicis-brevis-muscle$$, $$Kenhub: extensor pollicis brevis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: small, deep forearm muscle; extends the thumb at the carpometacarpal and MCP joints; with the abductor pollicis longus tendon forms the lateral border of the anatomical snuffbox; posterior interosseous nerve.$$),
  ($$A42$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/extensor-pollicis-brevis/22487$$, $$Elsevier Complete Anatomy, Quick Facts: extensor pollicis brevis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extends the proximal phalanx of the thumb at the first MCP joint and the first metacarpal at the first carpometacarpal joint; inserts on the dorsal base of the proximal phalanx.$$),
  ($$A43$$, $$https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3701420/$$, $$Jabir et al., The Extensor Pollicis Brevis: A Review of Its Anatomy and Variations (Eplasty)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: textbook descriptions of the EPB tendon disagree with published anatomical studies; in one cadaver study only a quarter of tendons inserted in the conventional way, into the base of the proximal phalanx.$$),
  ($$A44$$, $$https://www.statpearls.com/point-of-care/36135$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Extensor Pollicis Longus Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: thumb extensor at the MCP and IP joints (with some adduction); arises from the middle third of the posterior ulna, passes over Lister's tubercle and is the only occupant of the third extensor compartment; its tendon is the ulnar boundary of the anatomical snuffbox; posterior interosseous nerve. Updated 21 Dec 2022.$$),
  ($$A45$$, $$https://www.kenhub.com/en/library/anatomy/extensor-pollicis-longus-muscle$$, $$Kenhub: extensor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: main action is thumb extension at the MCP and interphalangeal joints, with a weak contribution to wrist extension.$$),
  ($$A46$$, $$https://www.kenhub.com/en/library/anatomy/supinator-muscle$$, $$Kenhub: supinator muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: spiral muscle of the deep part of the posterior compartment that wraps around the proximal radius and rotates it laterally (supination); found deep in the forearm, superficial only to the radius and ulna; posterior interosseous nerve.$$),
  ($$A47$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/supinator/21216$$, $$Elsevier Complete Anatomy, Quick Facts: supinator$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: supinates the forearm at the radioulnar joints; tested against resistance with the elbow extended, which keeps biceps brachii from contributing to supination.$$),
  ($$A48$$, $$https://www.kenhub.com/en/library/anatomy/anconeus-muscle$$, $$Kenhub: anconeus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: small triangular muscle at the back of the elbow from the lateral epicondyle to the lateral olecranon; helps extend the forearm at the elbow and helps stabilise the joint; some authors consider it a continuation of triceps; radial nerve.$$),
  ($$A49$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/anconeus-muscle/20503$$, $$Elsevier Complete Anatomy, Quick Facts: anconeus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: posterior and superficial to the elbow joint; extends the forearm at the elbow joint.$$),
  ($$A5$$, $$https://scholars.uky.edu/en/publications/the-function-of-brachioradialis/$$, $$The function of brachioradialis (University of Kentucky publication record)$$, null, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (record summary): fine-wire EMG in 10 healthy volunteers flexing the elbow with the forearm neutral, pronated or supinated at several loads found no difference in activation between the three positions; activity was higher when lifting than lowering. Authors and journal were not confirmed by the search.$$),
  ($$A50$$, $$https://www.ncbi.nlm.nih.gov/books/NBK519538/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Biceps Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction): a forearm flexor when the elbow is extended that becomes the forearm's most powerful supinator when the elbow is flexed; inserts on the radial tuberosity; musculocutaneous nerve.$$),
  ($$A51$$, $$https://www.ncbi.nlm.nih.gov/books/NBK551630/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Brachialis Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction): flexes the elbow in all physiological positions and is considered a pure flexor; no supination or pronation; lies in the anteroinferior arm, deeper than the biceps; inserts on the ulnar tuberosity.$$),
  ($$A52$$, $$https://www.ncbi.nlm.nih.gov/books/NBK536975/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Muscles$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction and structure): an anterior (flexor) and a posterior (extensor) compartment holding about twenty muscles, each subdivided into superficial and deep parts. Updated 5 Jun 2023.$$),
  ($$A53$$, $$https://www.kenhub.com/en/library/anatomy/the-superficial-flexors-of-the-forearm$$, $$Kenhub: superficial anterior forearm muscles$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: groups pronator teres, flexor carpi radialis, palmaris longus, flexor carpi ulnaris and flexor digitorum superficialis as superficial anterior muscles sharing the common flexor origin on the medial epicondyle (a teaching source places FDS in a middle layer beneath the first four).$$),
  ($$A54$$, $$https://www.kenhub.com/en/library/anatomy/the-superficial-extensors-of-the-forearm$$, $$Kenhub: superficial extensors of the forearm$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: brachioradialis, ECRL, ECRB, extensor digitorum, extensor digiti minimi and ECU form the superficial posterior group, mostly from the common extensor origin on the lateral epicondyle; anconeus is discussed with the arm muscles.$$),
  ($$A55$$, $$https://www.kenhub.com/en/library/anatomy/the-deep-extensors-of-the-forearm$$, $$Kenhub: deep extensors of the forearm$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the deep posterior group acts on the thumb and index finger, except the supinator, which acts on the proximal radioulnar joint. The group's members (supinator, abductor pollicis longus, extensor pollicis longus and brevis, extensor indicis) were listed in Kenhub's extensor indicis article (A37) rather than on this page's visible excerpt.$$),
  ($$A6$$, $$https://www.kenhub.com/en/library/anatomy/flexor-carpi-radialis-muscle$$, $$Kenhub: flexor carpi radialis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: fusiform muscle in the superficial layer of the anterior forearm; key facts list wrist flexion and wrist abduction (radial deviation); medial epicondyle to the bases of metacarpals 2–3; median nerve.$$),
  ($$A7$$, $$https://www.imaios.cn/en/e-anatomy/anatomical-structures/flexor-carpi-radialis-14216924$$, $$IMAIOS e-Anatomy: flexor carpi radialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (imaios.cn mirror): primary functions wrist flexion and radial deviation, with a minor role in pronation; cites the StatPearls forearm muscles article as its reference.$$),
  ($$A8$$, $$https://www.ncbi.nlm.nih.gov/books/NBK526051/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Flexor Carpi Ulnaris Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: superficial forearm flexor that flexes and adducts the hand; the most powerful wrist flexor; also a weak elbow flexor; humeral and ulnar heads; inserts on the pisiform, hook of hamate and fifth metacarpal; ulnar nerve. Updated 26 Jun 2023.$$),
  ($$A9$$, $$https://www.ncbi.nlm.nih.gov/books/NBK519516/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Palmaris Tendon$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (PubMed 30137801): small muscle whose contribution as an accessory flexor at the elbow and wrist is likely minimal; appears to tension the palmar aponeurosis; commonly absent, and absence has not been shown to reduce grip strength or cause another functional deficit.$$),
  ($$M1$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC4526813/$$, $$Kleiber, Kunz and Disselhorst-Klug, Muscular coordination of biceps brachii and brachioradialis in elbow flexion with respect to hand position (Frontiers in Physiology, 2015)$$, $$10.3389/fphys.2015.00215$$, $$emg$$, $$2026-10-16$$, $$16 healthy adults, slow single elbow flexions (20 degrees per second) with the hand pronated, neutral and supinated; surface EMG. The brachioradialis's contribution differed in pronation from supination and neutral, while biceps activity did not change with hand position; the authors relate this to the biceps's mechanical disadvantage in pronation. Acute, light task; other EMG studies disagree on the size of the position effect.$$),
  ($$M2$$, $$https://experts.mcmaster.ca/scholarly-works/1313379$$, $$Mogk and Keir, The effects of posture on forearm muscle loading during gripping (Ergonomics 46(9):956-975, 2003)$$, null, $$emg$$, $$2026-10-16$$, $$10 adults gripping a dynamometer at several efforts in three wrist and three forearm postures. Wrist-extensor activity accompanied gripping, was generally larger than flexor activity at low to moderate grip forces, and was always greater with the forearm pronated. Supports the wrist extensors steadying the wrist whenever the hand grips; a dynamometer is not a barbell, and EMG is not a growth measure.$$),
  ($$M3$$, $$https://doi.org/10.1016/j.physbeh.2020.113283$$, $$Jukic et al. (2021), lifting straps in the deadlift: movement velocity, grip strength and perceived grip security (Physiology & Behavior 229:113283)$$, $$10.1016/j.physbeh.2020.113283$$, $$biomechanics$$, $$2026-10-16$$, $$16 men deadlifting 4 sets of 4 with and without straps. With straps, grip strength fell less across the session and recovered faster, and grip felt more secure. Supports treating a strapped set's grip demand as different from an unstrapped one; it does not measure forearm muscle activity.$$),
  ($$M4$$, $$https://pubmed.ncbi.nlm.nih.gov/23101527/$$, $$Goetz et al., contribution of the flexor pollicis longus to pinch strength, measured before and after an EMG-guided lidocaine block (2012; PubMed 23101527)$$, null, $$biomechanics$$, $$2026-10-16$$, $$11 healthy volunteers; key, three-point and tip pinch strength fell after the flexor pollicis longus was temporarily blocked. Supports the long thumb flexor working in pinches; pinch-meter tasks, not plate pinches, and only the abstract was read.$$),
  ($$M5$$, $$https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12885837/$$, $$Kondi et al., An electromyographic study comparing muscle function during supination and pronation of the forearm (Cureus, 2026)$$, null, $$emg$$, $$2026-10-16$$, $$Pilot study, 4 adults, forearm held in neutral against a 1 kg load at increasing distances from the rotation axis (a lever). In supination the supinator was more active than the biceps at low torque and the biceps rose more steeply as torque increased; in pronation the pronator quadratus was more active at low torque and the pronator teres rose more steeply. Surface EMG for the pronators, fine wire for the supinator; isometric; very small sample.$$),
  ($$M6$$, $$https://pubmed.ncbi.nlm.nih.gov/12121684/$$, $$O'Sullivan and Gallwey, Upper-limb surface electro-myography at maximum supination and pronation torques: the effect of elbow and forearm angle (Journal of Electromyography and Kinesiology 12(4):275-285, 2002)$$, null, $$emg$$, $$2026-10-16$$, $$24 men, maximal pronation and supination efforts at four elbow angles and three forearm angles, surface EMG of six muscles including pronator teres, biceps and brachioradialis. Torque in both directions changed with elbow and forearm angle. Supports recording the elbow angle on the lever rows; maximal isometric efforts, not repetitions.$$),
  ($$M7$$, $$https://doi.org/10.1016/j.jelekin.2020.102428$$, $$Pratt, Hoffman, Grainger and Ditroilo, Forearm electromyographic activity during the deadlift exercise is affected by grip type and sex (Journal of Electromyography and Kinesiology, 2020)$$, $$10.1016/j.jelekin.2020.102428$$, $$emg$$, $$2026-10-16$$, $$Trained lifters deadlifting at 50, 70 and 90 per cent of their maximum with hook, mixed and double-overhand grips; forearm EMG changed with grip type and load. Cited only for that: secondary summaries disagree on which grip ranked highest, and the full text was not read.$$),
  ($$M8$$, $$https://anatomy.ttuhscep.edu/musculoskeletal_system/axilla_tables.html$$, $$Texas Tech University Health Sciences Center El Paso: axilla, posterior shoulder and arm muscle tables$$, null, $$anatomy$$, $$2026-10-16$$, $$The arm companion to S4, for the two upper-arm muscles the forearm atlas credits as external contributors: biceps brachii (elbow flexion, supination) and brachialis (elbow flexion only). Actions, not exercise loading.$$),
  ($$S1$$, $$https://doi.org/10.1007/s40279-025-02344-w$$, $$Pelland et al., The Resistance Training Dose Response: Meta-Regressions Exploring the Effects of Weekly Volume and Frequency on Muscle Hypertrophy and Strength Gains (Sports Medicine)$$, $$10.1007/s40279-025-02344-w$$, $$systematic_review$$, $$2026-10-16$$, $$Supports a positive volume–hypertrophy relationship with diminishing returns and fractional set counting as the best fit within the included studies. Does not set a forearm-muscle target.$$),
  ($$S2$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC11740565/$$, $$Ikeda et al., Effects of forearm rotation on wrist flexor and extensor muscle activities (Journal of Orthopaedic Surgery and Research, 2025)$$, $$10.1186/s13018-024-05363-x$$, $$emg$$, $$2026-10-16$$, $$Acute, controlled isometric tasks. Not a longitudinal hypertrophy study. Checked via web-search results on 16 Oct 2026: surface EMG of ECRB, ECU, FCR and FCU in 40 healthy arms at a constant wrist torque of three quarters of the neutral-position maximum, in pronation, neutral and supination. ECRB was more active in pronation, ECU did not change, FCR was more active in supination, FCU was lower in pronation than neutral. ECRL was not recorded separately.$$),
  ($$S3$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC1474175/$$, $$Butler, Kilbreath, Gorman and Gandevia, Selective recruitment of single motor units in human flexor digitorum superficialis muscle during flexion of individual fingers (Journal of Physiology, 2005)$$, $$10.1113/jphysiol.2005.089201$$, $$emg$$, $$2026-10-16$$, $$Finger-component specificity with coupling between fingers. Does not show complete isolation. Checked via web-search results on 16 Oct 2026 (abstract): isometric flexion of one finger at half of maximum activated fewer than half of the single units in FDS components of other fingers; recruitment at low force was mostly in adjacent fingers, with the ring and little fingers the most coupled.$$),
  ($$S4$$, $$https://anatomy.ttuhscep.edu/musculoskeletal_system/forearm_tables.html$$, $$Texas Tech University Health Sciences Center El Paso: forearm muscle reference (origins, insertions, actions)$$, null, $$anatomy$$, $$2026-10-16$$, $$Muscle identities and actions. This page did not appear in web-search results on 16 Oct 2026, so no claim cites it; the same site's alphabetical upper-limb reference (A38) did appear and is cited instead.$$),
  ($$S5$$, $$https://anatomy.ttuhscep.edu/musculoskeletal_system/forearm_ans.html$$, $$Texas Tech University Health Sciences Center El Paso: forearm dissection teaching material$$, null, $$anatomy$$, $$2026-10-16$$, $$Layers, orientation and identification. Not returned by web search on 16 Oct 2026; not cited by any claim.$$),
  ($$S6$$, $$https://pubmed.ncbi.nlm.nih.gov/31183837/$$, $$Rodrigues et al., Sonoanatomy of anterior forearm muscles (Journal of Ultrasound, 2019)$$, null, $$anatomy$$, $$2026-10-16$$, $$Superficial, intermediate and deep anterior structures. Checked via web-search results on 16 Oct 2026 (abstract and introduction only, PMC6704193): the anterior compartment's eight muscles split into superficial and deep groups. Layer-by-layer imaging findings were not seen.$$),
  ($$S7$$, $$https://anatomy.app/encyclopedia/flexor-carpi-radialis$$, $$Anatomy.app: flexor carpi radialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Superficial location and wrist action; not a quantified appearance claim. Not returned by web search on 16 Oct 2026; FCR claims cite A6 and A7 instead.$$),
  ($$S8$$, $$https://www.ncbi.nlm.nih.gov/sites/books/NBK526046/$$, $$StatPearls: flexor digitorum profundus$$, null, $$anatomy$$, $$2026-10-16$$, $$Deep extrinsic finger flexor identity and joint actions. Web search on 16 Oct 2026 could not confirm that this Bookshelf id is the FDP article; the StatPearls FDP article was found as PubMed 30252302 (A14), which the FDP claims cite instead.$$)
