-- Claims (key: <region>:<claim id>)
insert into specialization.claims as t (claim_key, node_id, kind, statement, basis, review_status, reviewed_on, review_note)
select x.claim_key, x.node_id, x.kind, x.statement, x.basis, 'draft', null, x.review_note
from (values
  ($$forearm:anconeus.appearance$$, $$forearm.anconeus$$, $$appearance$$, $$Anconeus is a small triangular muscle at the back of the elbow, between the thumb-side bony knob of the upper-arm bone and the point of the elbow. It may add to the contour at the back of the elbow; it is not a forearm growth target.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:anconeus.function$$, $$forearm.anconeus$$, $$function$$, $$Anconeus helps straighten the elbow and helps steady the joint; the triceps does most of the straightening.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:anterior.appearance$$, $$forearm.anterior$$, $$appearance$$, $$Together the palm-side muscles make up most of the palm-side fullness of the forearm. Which muscle shapes which part of that outline cannot be read from the surface.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:anterior.function$$, $$forearm.anterior$$, $$function$$, $$The palm-side (anterior) compartment holds the muscles that bend the wrist and fingers and turn the palm down. They lie in a surface layer, a middle layer (flexor digitorum superficialis) and a deep layer.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:apl.appearance$$, $$forearm.apl$$, $$appearance$$, $$APL is a deep muscle of the back of the forearm whose tendon, with EPB's, forms the thumb-side edge of the hollow at the base of the thumb. A visible line there is mostly tendon; the belly has little separately visible contour.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:apl.function$$, $$forearm.apl$$, $$function$$, $$Abductor pollicis longus moves the thumb out from the hand at its base (the carpometacarpal joint) and helps straighten it there.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:biceps.appearance$$, $$upper_arm.biceps$$, $$appearance$$, $$Biceps shapes the front of the upper arm. It is an upper-arm muscle and does not add forearm size.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:biceps.function$$, $$upper_arm.biceps$$, $$function$$, $$Biceps brachii bends the elbow and turns the forearm palm-up; with the elbow bent it is the forearm's most powerful palm-up muscle.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:br.appearance$$, $$forearm.br$$, $$appearance$$, $$Brachioradialis is the most superficial muscle on the thumb side of the forearm and forms the fleshy bulge in its upper half, so it may contribute to the thumb-side contour just below the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:br.function$$, $$forearm.br$$, $$function$$, $$Brachioradialis bends the elbow and is active whether the palm faces up, sideways or down. Anatomy references describe it as strongest with the forearm half-turned (thumb up). From a fully palm-up or palm-down start it also turns the forearm back toward thumb-up. It does not cross the wrist.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:br.selectivity.1$$, $$forearm.br$$, $$selectivity$$, $$Whether forearm position changes how hard the brachioradialis works when bending the elbow is unsettled. A surface-EMG study of 16 people found its share differed with the palm down compared with palm up or thumb up; a fine-wire EMG study of 10 people found no difference between the three positions. Neither study measured growth.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:brachialis.appearance$$, $$upper_arm.brachialis$$, $$appearance$$, $$Brachialis lies under the biceps in the lower front of the upper arm and may show at its sides. It is not a forearm muscle.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:brachialis.function$$, $$upper_arm.brachialis$$, $$function$$, $$Brachialis bends the elbow in every forearm position and does not turn the forearm; it is described as a pure elbow flexor.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.appearance$$, $$forearm.ecrb$$, $$appearance$$, $$ECRB is shorter than ECRL and partly covered by it on the back and thumb side of the forearm, so it belongs to the extensor mass there with only a partly visible outline of its own.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.function$$, $$forearm.ecrb$$, $$function$$, $$Extensor carpi radialis brevis bends the wrist back and is described as the main wrist extensor; with ECRL it tilts the hand toward the thumb side.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.selectivity.1$$, $$forearm.ecrb$$, $$selectivity$$, $$No ordinary exercise is known to train ECRB apart from ECRL. They share both wrist actions and lie side by side, and separating their EMG takes fine wires placed by measurement; surface electrodes record them together. The atlas does not split their work.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.selectivity.2$$, $$forearm.ecrb$$, $$selectivity$$, $$In a controlled study of 40 arms holding the same wrist-extension force, ECRB was more active with the palm turned down. Forearm rotation therefore belongs in how an exercise is described; the study does not show which position grows the muscle more, and it did not record ECRL.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrl.appearance$$, $$forearm.ecrl$$, $$appearance$$, $$ECRL starts just above the elbow on the thumb side and runs beside the brachioradialis in the surface layer of the back of the forearm, so it may contribute to the contour on the back and thumb side near the elbow.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrl.function$$, $$forearm.ecrl$$, $$function$$, $$Extensor carpi radialis longus bends the wrist back (extension) and tilts the hand toward the thumb side (radial deviation).$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrl.selectivity.1$$, $$forearm.ecrl$$, $$selectivity$$, $$No ordinary exercise is known to train ECRL apart from ECRB. Both bend the wrist back and toward the thumb side, they lie side by side, and EMG texts long held that their activity could not be told apart even with needle electrodes: recording them separately takes fine wires placed by measurement, and surface electrodes record them together. The atlas does not split their work.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecu.appearance$$, $$forearm.ecu$$, $$appearance$$, $$ECU runs in the surface layer along the pinky-side edge of the back of the forearm, from the elbow to the wrist, so it may contribute to the contour there.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ecu.function$$, $$forearm.ecu$$, $$function$$, $$Extensor carpi ulnaris bends the wrist back (with ECRL and ECRB) and tilts the hand toward the pinky side (with FCU).$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecu.selectivity.1$$, $$forearm.ecu$$, $$selectivity$$, $$In the controlled wrist-extension study, ECU activity did not change between palm up, thumb up and palm down. That is one acute finding, not evidence that forearm position never matters for ECU.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ed.appearance$$, $$forearm.ed$$, $$appearance$$, $$Extensor digitorum lies in the middle of the back of the forearm in the surface layer and splits into four tendons about a third of the way down, so it may contribute to the central mass on the back of the forearm. Its tendons on the back of the hand are not muscle bulk.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ed.function$$, $$forearm.ed$$, $$function$$, $$Extensor digitorum straightens the four fingers, mainly at the knuckles (MCP) and also at their other joints, and helps bend the wrist back.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:edm.appearance$$, $$forearm.edm$$, $$appearance$$, $$EDM is a thin muscle on the pinky side of extensor digitorum, joined to it near the elbow and separate from about mid-forearm; some anatomists treat it as part of extensor digitorum. It is not a major independent driver of forearm width.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:edm.function$$, $$forearm.edm$$, $$function$$, $$Extensor digiti minimi straightens the little finger, mainly at the knuckle, and can do so independently of the other fingers.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ei.appearance$$, $$forearm.ei$$, $$appearance$$, $$Extensor indicis is a narrow muscle in the deep layer of the back of the forearm near the wrist, so it has little or no separately visible contour.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ei.function$$, $$forearm.ei$$, $$function$$, $$Extensor indicis straightens the index finger at its knuckle and other joints, which lets the index finger straighten on its own.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:epb.appearance$$, $$forearm.epb$$, $$appearance$$, $$EPB is small and deep. Its tendon, with APL's, forms the thumb-side edge of the hollow at the base of the thumb, so a visible tendon there says little about the size of the muscle belly.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:epb.function$$, $$forearm.epb$$, $$function$$, $$Extensor pollicis brevis straightens the thumb at its knuckle (MCP) and helps straighten it at its base.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:epb.variation.1$$, $$forearm.epb$$, $$variation$$, $$Where the EPB tendon attaches varies a good deal between people; in one cadaver study only a quarter of tendons attached in the textbook way, at the base of the thumb's first bone.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:epl.appearance$$, $$forearm.epl$$, $$appearance$$, $$EPL lies in the deep layer of the back of the forearm. Its long tendon passes around a bony bump on the back of the radius (Lister's tubercle) and forms the pinky-side edge of the hollow at the base of the thumb; the belly has little or no separately visible contour.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:epl.function$$, $$forearm.epl$$, $$function$$, $$Extensor pollicis longus straightens the tip (IP joint) of the thumb and also straightens the thumb at its knuckle (MCP).$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcr.appearance$$, $$forearm.fcr$$, $$appearance$$, $$FCR lies in the surface layer of the palm side, slanting from the pinky side of the elbow toward the thumb side of the wrist, so it may contribute to the palm-side contour toward the thumb side. It is not the whole thumb-side width; the brachioradialis forms that edge.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fcr.function$$, $$forearm.fcr$$, $$function$$, $$Flexor carpi radialis bends the wrist toward the palm and tilts the hand toward the thumb side (radial deviation).$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcr.selectivity.1$$, $$forearm.fcr$$, $$selectivity$$, $$In a controlled study of 40 arms holding the same wrist-flexion force, FCR was more active with the palm turned up than with the thumb up or the palm down. Forearm rotation therefore belongs in how an exercise is described; the study does not show which position grows the muscle more.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcu.appearance$$, $$forearm.fcu$$, $$appearance$$, $$FCU runs in the surface layer along the pinky-side edge of the palm side, from the elbow to the wrist, so it may contribute to the palm-side ulnar contour. Visible shape also depends on neighbouring muscles and individual anatomy.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fcu.function$$, $$forearm.fcu$$, $$function$$, $$Flexor carpi ulnaris bends the wrist toward the palm and tilts the hand toward the pinky side (ulnar deviation). Anatomy references describe it as the most powerful wrist flexor.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcu.selectivity.1$$, $$forearm.fcu$$, $$selectivity$$, $$In the same controlled wrist-flexion study, FCU was less active with the palm turned down than with the thumb up. This is evidence that forearm rotation changes wrist-flexor activity, not that one position grows FCU more.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fdp.appearance$$, $$forearm.fdp$$, $$appearance$$, $$FDP lies in the deep layer of the palm side, against the ulna under the other finger flexors, and is hard to feel through the skin. It may add to overall palm-side thickness but has little or no separately visible surface contour, so it cannot be drawn as an isolated surface stripe.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fdp.function$$, $$forearm.fdp$$, $$function$$, $$Flexor digitorum profundus is the only muscle that bends the four fingers at their end (DIP) joints. It also helps bend the middle joints, the knuckles and the wrist. The force it makes at the fingertips depends on wrist position and falls when the wrist is fully bent.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fdp.selectivity.1$$, $$forearm.fdp$$, $$selectivity$$, $$Ordinary gym grip and finger-flexion exercises load FDP together with FDS. In a video-EMG study of fist making, FDP did most of the work in a light fist and FDS joined in every tight fist. No ordinary exercise has been shown to train FDP apart from FDS, so the atlas shows the work as shared and invents no split.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.appearance$$, $$forearm.fds$$, $$appearance$$, $$FDS forms the middle layer of the palm side, covered by the surface wrist flexors and lying over the deep finger flexor, so it may add to the general fullness of the palm side but has no separately visible outline.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.function$$, $$forearm.fds$$, $$function$$, $$Flexor digitorum superficialis is the main muscle bending the four fingers at their middle (PIP) joints. It also helps bend the knuckles (MCP) and the wrist. It has a separate part, with its own tendon, for each finger.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.selectivity.1$$, $$forearm.fds$$, $$selectivity$$, $$The finger parts of FDS can be recruited selectively to some degree, with coupling between fingers. When one finger flexed at half its maximum force, fewer than half of the motor units serving the other fingers' parts became active, and units serving a neighbouring finger were recruited most readily. This supports describing finger actions; it does not show that one finger's part can be trained in isolation.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.selectivity.2$$, $$forearm.fds$$, $$selectivity$$, $$Ordinary gym grip and finger-flexion exercises load FDS together with the deep finger flexor (FDP). In a video-EMG study of fist making, FDP did most of the work in a light fist and FDS joined in every tight fist, in an order that differed between people. No ordinary exercise has been shown to split the work between them, so the atlas shows it as shared and invents no split.$$, $$experimental$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fpl.appearance$$, $$forearm.fpl$$, $$appearance$$, $$FPL lies in the deep layer on the thumb side of the palm side, close to the radius and under the surface and middle flexors, so it has little or no separately visible contour.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fpl.function$$, $$forearm.fpl$$, $$function$$, $$Flexor pollicis longus is the only muscle that bends the tip (IP joint) of the thumb, and it also helps bend the thumb at its knuckle.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pl.appearance$$, $$forearm.pl$$, $$appearance$$, $$Palmaris longus has a small belly near the elbow and a long tendon, and it is missing in some people, so it is not a major driver of forearm width. Any contribution would be to the middle of the palm-side contour near the elbow.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:pl.function$$, $$forearm.pl$$, $$function$$, $$Palmaris longus tenses the sheet of connective tissue in the palm (palmar aponeurosis). It crosses the wrist but is small, so its help in bending the wrist is likely minimal.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pl.variation.1$$, $$forearm.pl$$, $$variation$$, $$Palmaris longus is absent on one or both sides in a minority of people, and how often depends strongly on the population. A review pooling 26 clinical studies found the lowest rates in East and South-East African groups and the highest in Arab Middle Eastern groups, so no single figure applies to everyone. Its absence has not been shown to reduce grip strength.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:posterior.appearance$$, $$forearm.posterior$$, $$appearance$$, $$Together the back-of-forearm muscles make up the back of the forearm and, through the brachioradialis and the thumb-side wrist extensors, the thumb-side outline near the elbow.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:posterior.function$$, $$forearm.posterior$$, $$function$$, $$The back (posterior) compartment holds the muscles that straighten the wrist, fingers and thumb and turn the palm up, plus the brachioradialis, which bends the elbow. They lie in a surface layer and a deep layer.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pq.appearance$$, $$forearm.pq$$, $$appearance$$, $$Pronator quadratus is the most distal muscle of the deepest palm-side layer, a flat square muscle on the bones just above the wrist under the flexor tendons, so it has little or no direct surface definition.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:pq.function$$, $$forearm.pq$$, $$function$$, $$Pronator quadratus turns the forearm palm-down (pronation). It is also a dynamic stabiliser of the joint between the two forearm bones at the wrist (the distal radioulnar joint), pressing them together.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pt.appearance$$, $$forearm.pt$$, $$appearance$$, $$Pronator teres lies in the surface layer just below the elbow, slanting from the pinky side of the elbow to the middle of the radius on the thumb side, and forms the pinky-side edge of the hollow in front of the elbow. It may contribute to the slanted palm-side contour there.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:pt.function$$, $$forearm.pt$$, $$function$$, $$Pronator teres turns the forearm palm-down (pronation) and gives a small amount of help bending the elbow.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:supinator.appearance$$, $$forearm.supinator$$, $$appearance$$, $$Supinator lies in the deep layer just below the elbow, wrapped around the top of the radius under the surface extensors, so it is not directly visible in an ordinary surface view.$$, $$anatomical_inference$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:supinator.function$$, $$forearm.supinator$$, $$function$$, $$Supinator turns the forearm palm-up (supination) at the joint between the forearm bones near the elbow. With the elbow bent, the biceps is the stronger palm-up muscle; with the elbow straight, the biceps contributes little.$$, $$established_anatomy$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$)
) as x (claim_key, node_id, kind, statement, basis, review_note)
on conflict (claim_key) do update set node_id = excluded.node_id, kind = excluded.kind, statement = excluded.statement, basis = excluded.basis, review_note = excluded.review_note
  where (t.node_id, t.kind, t.statement, t.basis, t.review_note) is distinct from (excluded.node_id, excluded.kind, excluded.statement, excluded.basis, excluded.review_note);

