-- Variant dimensions (counting: the calculator, the logger and publication rule 11 read them; descriptive: mapping rationales cite them)
insert into specialization.variant_dimensions as t (id, label, sort_order, kind) values
  ($$sided_by$$, $$Limb whose side is recorded$$, 0, $$counting$$),
  ($$leg_laterality$$, $$Legs$$, 1, $$counting$$),
  ($$side_anchor$$, $$The leg a recorded side names$$, 2, $$counting$$),
  ($$knee$$, $$Knee$$, 3, $$descriptive$$),
  ($$hip$$, $$Hip$$, 4, $$descriptive$$),
  ($$torso$$, $$Torso$$, 5, $$descriptive$$),
