  ($$grip_width$$, $$Grip width$$, 8, $$descriptive$$),
  ($$stance$$, $$Stance$$, 9, $$descriptive$$),
  ($$range$$, $$Range of motion$$, 10, $$descriptive$$)
on conflict (id) do update set label = excluded.label, sort_order = excluded.sort_order, kind = excluded.kind
  where (t.label, t.sort_order, t.kind) is distinct from (excluded.label, excluded.sort_order, excluded.kind);

