insert into specialization.variant_mappings as t (version_id, mapping_key, variant_key, node_id, action_id, relationship, muscle_mode, evidence_basis, allocation, requires_no_straps, rationale, review_status, side_relation)
select v.id, x.mapping_key, x.variant_key, x.node_id, x.action_id, x.relationship, x.muscle_mode, x.evidence_basis, x.allocation, x.requires_no_straps, x.rationale, x.review_status, x.side_relation
from (values
  ($$forearm_mappings_v1$$, $$cat-121:forearm.br$$, $$cat-121$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachioradialis is an elbow flexor and moves through range in every curl, so it gets dynamic credit; with the palms up it is a helper rather than the curl's target, so it is contributing, not direct.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-121:forearm.fdp$$, $$cat-121$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-121:forearm.fds$$, $$cat-121$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$, $$same$$),
