  ($$forearm_mappings_v1$$, $$cat-135:forearm.fds$$, $$cat-135$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-135:upper_arm.biceps$$, $$cat-135$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$emg$$, $$individual$$, false, $$The biceps still helps flex the elbow with the palms down, at a mechanical disadvantage (M1), so it is contributing.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-135:upper_arm.brachialis$$, $$cat-135$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-136:forearm.br$$, $$cat-136$$, $$forearm.br$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$inference$$, $$individual$$, false, $$Each rep is lowered with the palms down, where the brachioradialis's share of elbow flexion changes (M1), and lifted palms up, where it helps; together that makes it a direct target. The turn at the top is not credited to the pronators or the supinator: a dumbbell turned about its own handle gives little resistance to the turn.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-136:forearm.ecrb$$, $$cat-136$$, $$forearm.ecrb$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$On the palms-down lowering the wrist extensors hold the wrist straight against the load without moving it: isometric stabilization, not wrist-extension reps (M2 documents extensor activity with a pronated grip).$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-136:forearm.ecrl$$, $$cat-136$$, $$forearm.ecrl$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$On the palms-down lowering the wrist extensors hold the wrist straight against the load without moving it: isometric stabilization, not wrist-extension reps (M2 documents extensor activity with a pronated grip).$$, $$reviewed$$, $$same$$),
