  ($$forearm_mappings_v1$$, $$cat-136:forearm.fds$$, $$cat-136$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-136:upper_arm.biceps$$, $$cat-136$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$Each rep is lifted with the palms up, the biceps's strongest position for flexing the elbow. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-136:upper_arm.brachialis$$, $$cat-136$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-137:forearm.br$$, $$cat-137$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachioradialis is an elbow flexor and moves through range in every curl, so it gets dynamic credit; with the palms up it is a helper rather than the curl's target, so it is contributing, not direct.$$, $$reviewed$$, $$same$$),
