  ($$forearm_mappings_v1$$, $$cat-137:forearm.fds$$, $$cat-137$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-137:upper_arm.biceps$$, $$cat-137$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A palms-up curl is built on elbow flexion with the forearm supinated, the position in which the biceps flexes the elbow best. It is credited as an upper-arm muscle beside the forearm, not as forearm work.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-137:upper_arm.brachialis$$, $$cat-137$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$, $$same$$),
