  ($$forearm_mappings_v1$$, $$cat-138:forearm.fdp$$, $$cat-138$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The hands hold the bar against body weight while the elbows bend: an incidental grip, shared between FDS and FDP. Straps would take it off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-138:forearm.fds$$, $$cat-138$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The hands hold the bar against body weight while the elbows bend: an incidental grip, shared between FDS and FDP. Straps would take it off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$, $$same$$),
