  ($$forearm_mappings_v1$$, $$cat-139:forearm.fdp$$, $$cat-139$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.fds$$, $$cat-139$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.pl$$, $$cat-139$$, $$forearm.pl$$, $$wrist.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The palmaris longus is a weak wrist flexor, so it helps rather than leads; it is absent in some people, and its credit means nothing for them.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.ecrb$$, $$cat-140$$, $$forearm.ecrb$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis brevis's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$, $$same$$),
