  ($$forearm_mappings_v1$$, $$cat-141:forearm.fdp$$, $$cat-141$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the roller's handle throughout: incidental grip, shared between FDS and FDP.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.fds$$, $$cat-141$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the roller's handle throughout: incidental grip, shared between FDS and FDP.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-142:forearm.fdp$$, $$cat-142$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, false, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps do not apply to a pinch. The hand's own muscles also work in a pinch and are not credited to the forearm.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-142:forearm.fds$$, $$cat-142$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, false, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps do not apply to a pinch. The hand's own muscles also work in a pinch and are not credited to the forearm.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-142:forearm.fpl$$, $$cat-142$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$individual$$, false, $$The thumb presses the plates against the fingers for the whole hold, and the long thumb flexor adds measurably to pinch strength (M4), so it is a direct isometric target in a pinch.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-143:forearm.fdp$$, $$cat-143$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-143:forearm.fds$$, $$cat-143$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-144:forearm.fdp$$, $$cat-144$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Gripping a towel closes the fist further than a bar. Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-144:forearm.fds$$, $$cat-144$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Gripping a towel closes the fist further than a bar. Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-144:forearm.fpl$$, $$cat-144$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$contributing$$, $$isometric$$, $$inference$$, $$individual$$, false, $$The thumb wraps the towel and presses on it, so the long thumb flexor likely helps hold; how much is not established, so this stays pending review.$$, $$draft$$, $$same$$),
