  ($$forearm_mappings_v1$$, $$cat-299:forearm.fpl$$, $$cat-299$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$contributing$$, $$isometric$$, $$inference$$, $$individual$$, false, $$The thumb closes over the handle, so the long thumb flexor likely helps hold it; how much it is loaded in a handle grip, as opposed to a pinch, is not established, so this stays pending review.$$, $$draft$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-300:forearm.br$$, $$cat-300$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$isometric$$, $$anatomy$$, $$individual$$, false, $$The bar sits in the crook of the elbows, and the elbow flexors hold the elbows bent against it for the whole carry. The hands do not grip the bar, so no finger flexor is credited.$$, $$reviewed$$, $$same$$),
