  ($$forearm_mappings_v1$$, $$cat-406:forearm.supinator$$, $$cat-406$$, $$forearm.supinator$$, $$forearm.supination$$, $$direct$$, $$dynamic$$, $$emg$$, $$shared$$, false, $$Turning the forearm palm-up against a lever is supination. The supinator led at low torque in a lever task, with the biceps rising as torque grew (M5), and torque changes with the elbow angle (M6): with the elbow bent, as this row defines it, the biceps shares the work, so this is not supinator-only.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-406:upper_arm.biceps$$, $$cat-406$$, $$upper_arm.biceps$$, $$forearm.supination$$, $$contributing$$, $$dynamic$$, $$emg$$, $$shared$$, false, $$With the elbow bent the biceps is a strong supinator and joins in as the load grows (M5, M6); it is credited as contributing, as an upper-arm muscle beside the forearm.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-407:forearm.ecrb$$, $$cat-407$$, $$forearm.ecrb$$, $$wrist.radial_deviation$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Tilting the hand toward the thumb side is done by the flexor and extensor on that side together, so each is direct and the work is shared; how the split moves with a slightly flexed or extended wrist is not known, so no split is given.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-407:forearm.ecrl$$, $$cat-407$$, $$forearm.ecrl$$, $$wrist.radial_deviation$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Tilting the hand toward the thumb side is done by the flexor and extensor on that side together, so each is direct and the work is shared; how the split moves with a slightly flexed or extended wrist is not known, so no split is given.$$, $$reviewed$$, $$same$$),
