  ($$forearm_mappings_v1$$, $$cat-408:forearm.fdp$$, $$cat-408$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-408:forearm.fds$$, $$cat-408$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.ecrb$$, $$cat-409$$, $$forearm.ecrb$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.ecrl$$, $$cat-409$$, $$forearm.ecrl$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.ecu$$, $$cat-409$$, $$forearm.ecu$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.fdp$$, $$cat-409$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the load off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.fds$$, $$cat-409$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the load off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.fpl$$, $$cat-409$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$contributing$$, $$isometric$$, $$inference$$, $$individual$$, false, $$The thumb closes over the handle, so the long thumb flexor likely helps hold it; how much it is loaded in a handle grip, as opposed to a pinch, is not established, so this stays pending review.$$, $$draft$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.fcr$$, $$cat-410$$, $$forearm.fcr$$, $$wrist.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A wrist curl is built on wrist flexion, the flexor carpi radialis's main action; the wrist moves through range against the load.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.fcu$$, $$cat-410$$, $$forearm.fcu$$, $$wrist.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A wrist curl is built on wrist flexion, the flexor carpi ulnaris's main action; the wrist moves through range against the load.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.fdp$$, $$cat-410$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.fds$$, $$cat-410$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.pl$$, $$cat-410$$, $$forearm.pl$$, $$wrist.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The palmaris longus is a weak wrist flexor, so it helps rather than leads; it is absent in some people, and its credit means nothing for them.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ecrb$$, $$cat-411$$, $$forearm.ecrb$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis brevis's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ecrl$$, $$cat-411$$, $$forearm.ecrl$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis longus's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ecu$$, $$cat-411$$, $$forearm.ecu$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi ulnaris's main actions; the wrist moves through range against the load.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ed$$, $$cat-411$$, $$forearm.ed$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The extensor digitorum assists wrist extension, but its main job is straightening the fingers, which stay closed on the bar; it is contributing, not direct. This is wrist extension, not finger extension.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.fdp$$, $$cat-411$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.fds$$, $$cat-411$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-412:forearm.fpl$$, $$cat-412$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$Bending the tip of the thumb against a band is the long thumb flexor's own action (the only muscle that bends the thumb's end joint); small-muscle coverage, not a high-volume default.$$, $$reviewed$$, $$same$$),
  ($$forearm_mappings_v1$$, $$cat-413:forearm.epb$$, $$cat-413$$, $$forearm.epb$$, $$thumb.mcp_extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Straightening the thumb at its knuckle against a band is the extensor pollicis brevis's action, shared with the longus, which straightens the tip.$$, $$reviewed$$, $$same$$),
