from (values
  ($$forearm_mappings_v1$$, $$cat-121:forearm.br$$, $$S4$$, $$Forearm muscle tables: brachioradialis (action)$$, $$An anatomy table gives the muscle's action, not how much this exercise loads it.$$, 0),
